const bytecode = "";

console.log('Testing Safe execTransaction decoding...');
console.log('Bytecode length:', bytecode.length);
console.log('Selector:', bytecode.slice(0, 10));

// Make request to the decompile API
fetch('http://localhost:3002/api/decompile', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    bytecode: bytecode,
    chainId: 1
  })
})
.then(response => response.json())
.then(data => {
  console.log('\nRaw response:', JSON.stringify(data, null, 2));
  
  if (data.success && data.analysis) {
    console.log('\nParsed result:');
    console.log('Function:', data.analysis.decompiled.functionName);
    console.log('Signature:', data.analysis.decompiled.signature);
    console.log('Parameters:', data.analysis.decompiled.decodedParams);
    
    // Check if there's nested transaction data
    if (data.analysis.decompiled.decodedParams && data.analysis.decompiled.decodedParams[2]) {
      const nestedData = data.analysis.decompiled.decodedParams[2];
      if (nestedData.startsWith('0xa9059cbb')) {
        console.log('\nNested ERC20 transfer detected!');
        console.log('Transfer data:', nestedData);
      }
    }
  }
})
.catch(error => {
  console.error('Error:', error);
});